// Small deterministic content build. No network, secrets, packages, or runtime HTML rendering.
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { renderPage, RELEASE } from './site-shell.mjs';
import { writingPages } from './writing-pages.mjs';
import { HOME_PAGE } from './home-page.mjs';
import { ARTICLE_TYPES, TEMPLATES, EXAMPLES } from '../public/content-data.js';
import { createMarkdown } from '../public/markdown.js';
import { createArticleMarkdown } from '../public/article-markdown.js';
import { createWordDocument } from '../public/word-export.js';
import { WORD_MARKDOWN_SAMPLE } from './word-markdown-tool.mjs';
const esc = value => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#39;');
const a = (href, text, cls = '') => `<a href="${href}"${cls ? ` class="${cls}"` : ''}>${text}</a>`;
const li = items => `<ul>${items.map(item => `<li>${item}</li>`).join('')}</ul>`;
const notice = text => `<aside class="notice">${text}</aside>`;
const steps = items => `<ol class="task-steps">${items.map(([title, text]) => `<li><h2>${title}</h2><p>${text}</p></li>`).join('')}</ol>`;
const cards = items => `<div class="resource-grid">${items.map(([title, text, link, action]) => `<article class="paper"><h2>${title}</h2><p>${text}</p>${a(link, action)}</article>`).join('')}</div>`;
const status = '<strong>In development.</strong> Public examples, templates, the sample editor, and the writing workspace need no account. AI generation is restricted to the owner and invited testers, and requires private setup. Nothing is published automatically.';
const pages = new Map();
function add(path, title, description, body, { script = false, wide = false } = {}) {
  pages.set(path, renderPage({ route: path, title, description, body, script: script ? '/resources.js' : '', wide }));
}
const heading = (label, title, intro) => `<header class="page-intro"><p class="eyebrow">${label}</p><h1>${title}</h1><p class="lead">${intro}</p></header>`;
add('/', 'Prepare your draft for WordPress', 'Convert Word, Google Docs, or Markdown into editable WordPress blocks. Free local tools, a readable preview, and no account needed.', HOME_PAGE, { wide: true });

add('/templates/', 'Note templates', 'Six copyable note outlines for personal essays, project updates, and practical guides. Prepare source material without inventing missing facts.', `${heading('Start with your material', 'A better starting point than a blank box.', 'Choose an outline, fill it in using your own facts, and mark what you do not know. These templates work with or without pilot access.')}
${notice('Copying an outline does not send it to AI or open a session. Keep a copy in your own document. Do not put private notes in a URL or a public GitHub issue.')}
<nav class="jump-links" aria-label="Choose a template">${TEMPLATES.map(t => a(`#${t.id}`, t.title)).join('')}</nav><p id="resource-status" class="message" role="status" aria-live="polite"></p>
<div class="template-grid">${TEMPLATES.map(t => `<article class="paper template" id="${t.id}"><p class="eyebrow">${ARTICLE_TYPES[t.profile]}</p><h2>${t.title}</h2><p>${t.purpose}</p><label for="outline-${t.id}">Copyable outline</label><textarea id="outline-${t.id}" rows="8" readonly>${esc(t.outline)}</textarea><button type="button" class="secondary" data-copy="outline-${t.id}">Copy ${t.title.toLowerCase()} outline</button><details><summary>Fictional filled example</summary><p>${esc(t.example)}</p></details><p class="small"><strong>Keep this boundary:</strong> ${t.caution}</p><p>${a('/write/#template-' + t.id, 'Use this outline in the workspace', 'button')}</p></article>`).join('')}</div><noscript><p>JavaScript is off. Select the visible outline text and copy it manually.</p></noscript><p>${a('/guides/source-notes/', 'Learn how to prepare stronger source notes')} or ${a('/demo/', 'try the sample editor')}.</p>`, { script: true, wide: true });

function sampleBody(body) {
  return body.split('\n\n').map(block => block.startsWith('## ') ? `<h4>${esc(block.slice(3))}</h4>` : /^1\. /.test(block) ? `<ol>${block.split('\n').map(line => `<li>${esc(line.replace(/^\d+\. /, ''))}</li>`).join('')}</ol>` : `<p>${esc(block)}</p>`).join('');
}
add('/examples/', 'Complete article examples', 'Compare source notes with three fictional article packages, including page details, review questions, and downloadable sample Markdown.', `${heading('Illustrative examples', 'See the whole package, not just the prose.', 'Each example below was written to explain the workflow. None is a live model response, customer result, or verified personal experience.')}
<nav class="jump-links" aria-label="Choose an example">${EXAMPLES.map(e => a(`#${e.id}`, e.label)).join('')}</nav>
${EXAMPLES.map(e => `<section id="${e.id}" class="example-section"><p class="eyebrow">Illustrative example / ${ARTICLE_TYPES[e.profile]}</p><h2>${e.label}</h2><div class="example-grid"><article class="paper source"><h3>The supplied notes</h3><p>${esc(e.notes)}</p><dl><dt>Audience</dt><dd>${esc(e.audience)}</dd><dt>Purpose</dt><dd>${esc(e.purpose)}</dd></dl></article><article class="paper sample-article"><p class="eyebrow">A possible article</p><h3>${esc(e.draft.title)}</h3>${sampleBody(e.draft.body)}</article></div><div class="example-grid"><article class="paper"><h3>The page details</h3><dl><dt>Excerpt</dt><dd>${esc(e.draft.excerpt)}</dd><dt>Page description</dt><dd>${esc(e.draft.description)}</dd><dt>Filename</dt><dd><code>${e.draft.slug}.md</code></dd></dl>${a(`/samples/${e.id}.md`, 'Open sample Markdown')} · <a href="/samples/${e.id}.md" download="${e.draft.slug}.md">Download sample</a></article><article class="paper"><h3>What needs a human decision</h3><p>${esc(e.decision)}</p>${li(e.draft.questions.map(esc))}<p class="small">These are teaching questions, not evidence that an independent fact-check occurred.</p></article></div></section>`).join('')}
${notice('Sample downloads contain fictional article text and metadata, but not source notes or review questions. Do not present a fictional first-person example as your own experience.')}
<div class="actions">${a('/demo/', 'Edit a sample yourself', 'button')}${a('/templates/', 'Prepare your own notes')}${a('/help/markdown-export/', 'Read the export guide')}</div>`, { wide: true });

add('/demo/', 'Try the sample editor', 'Edit a prewritten fictional article, review it, and export Markdown in your browser. No account and no live AI generation.', `${heading('Public sample editor', 'Try editing and exporting a page.', 'This editor loads prewritten fictional examples. It does not generate writing, call an AI service, or publish anything.')}
${notice('<strong>No autosave.</strong> Edits stay in this open page and can be lost when you refresh or leave. Download what you want to keep. Do not enter sensitive material.')}
<div id="demo"><div class="paper"><label for="demo-example">Choose a prewritten example</label><select id="demo-example">${EXAMPLES.map(e => `<option value="${e.id}">${e.label}</option>`).join('')}</select><button id="demo-load" class="secondary" type="button">Load selected sample</button></div><p id="resource-status" class="message" role="status" aria-live="polite"></p><div class="workspace"><section class="pilot-card"><h2>The fictional source</h2><p id="demo-notes"></p><h3>Questions to check</h3><ul id="demo-questions"></ul><p class="small">This is an editorial demonstration, not a model-quality test. Select a sample above, then edit the article fields. Changing a field clears approval.</p>${a('/examples/', 'Read all complete examples')}</section><section class="pilot-card"><h2>Your editable sample</h2><label for="demo-title">Article title</label><input id="demo-title" maxlength="160"><label for="demo-excerpt">Short excerpt</label><textarea id="demo-excerpt" rows="3" maxlength="300"></textarea><label for="demo-description">Page description</label><textarea id="demo-description" rows="3" maxlength="160"></textarea><label for="demo-slug">Filename, without .md</label><input id="demo-slug" maxlength="80" spellcheck="false"><label for="demo-body">Article body, in Markdown</label><textarea id="demo-body" rows="16" maxlength="60000"></textarea><label class="check"><input id="demo-reviewed" type="checkbox"><span>I have reviewed this sample and understand that exporting does not publish it.</span></label><div class="actions"><button id="demo-download" type="button" class="button" disabled>Download Markdown</button><button id="demo-copy" type="button" class="secondary" disabled>Copy Markdown</button></div><p class="small">The file includes <code>draft: true</code>, not a universal publication lock. Notes and review questions are omitted. ${a('/help/markdown-export/', 'What to do with your export')}</p></section></div></div><noscript><p>The editor needs JavaScript. ${a('/examples/', 'Read the examples and download the same sample files without JavaScript.')} No AI access is required.</p></noscript>`, { script: true, wide: true });

add('/getting-started/', 'Getting started', 'Start from notes or an existing draft, review the article, and choose a useful export without an account.',
heading('First-use guide', 'One article. A clear next step.', 'The public writing workspace is manual. Choose the starting point that matches what you already have.') +
cards([['I have notes', 'Load an outline and keep facts and uncertainty beside your article.', '/write/#notes', 'Start with notes'], ['I have a draft', 'Paste the body and finish the article before adding page details.', '/write/#draft', 'Edit an existing draft'], ['I want to practice', 'Try a fictional article in the same workspace and exports.', '/write/#sample', 'Try a working sample']]) +
'<h2>From notes to an article</h2><ol><li>Choose an outline and replace its prompts with your facts.</li><li>Write in the article editor, or copy a locally prepared drafting brief into your chosen tool and bring back the result. This site makes no AI request during that public workflow.</li><li>Compare the draft with your source. Resolve unsupported claims and preserve uncertainty.</li><li>Run optional draft checks, read the preview, edit, and check the review box. <a href="/help/draft-checks/">Understand the local checks</a>.</li></ol>' +
'<h2>Choose your publishing handoff</h2><p>Copy formatted writing into an editor, with its title only when selected. Or download a publishing kit with the article body, reading HTML, page fields, and destination instructions. The kit includes complete page Markdown only when its fields are ready. <a href="/help/publishing-handoff/">Choose the right handoff</a>.</p><h2>Choose what to take away</h2><p>Copy or download the article body without page metadata. Add a title to download a standalone HTML reading page. Fill the page details for Markdown with metadata; select whether the website supplies the title heading. <a href="/help/markdown-export/">Choose the right export</a>.</p>' +
'<h2>Bring a draft back</h2><p>Use Import an article to preview an exported Markdown file or the structured result requested by the drafting brief. Source notes are kept. Add questions and answers in Review questions &amp; notes. <a href="/help/article-import/">Learn about importing</a>.</p><h2>Keep unfinished work</h2><p>Use an explicit private workspace backup to preserve notes and article fields. Check the actual downloaded file before leaving. There is no autosave or account history. <a href="/help/local-workspace/">Learn how save and restore work</a>.</p>' +
'<h2>Already invited to the AI pilot?</h2><p><a href="/pilot">Open the private pilot</a> when owner activation is complete. It sends notes to Anthropic only after consent and an explicit generation request. Its access, shared quotas, and real-provider acceptance testing remain separate from the public workspace. <a href="/access/">Read the access guidance</a>.</p>');
add('/help/markdown-export/', 'Choose the right export', 'Choose body Markdown, page Markdown with optional title heading, or a standalone HTML reading page for your own publishing workflow.',
heading('Export guide', 'An article you can take with you.', 'Choose the format your next step needs. Downloading a file does not publish it.') +
'<h2 id="article-markdown">Take an article as Markdown</h2><p>Select Markdown article (.md) as your destination. Read the preview, choose whether to include the separate title as a heading when available, and check the review box. Copy article Markdown or download a .md file without filling an excerpt, description, or filename field. The title choice is shared with Markdown with page details. No title is added when the separate title field is empty, and authored title headings in the body are kept.</p><p>The body keeps its current Markdown text, with a final newline added when needed. Unsupported syntax and literal HTML remain in the file; your destination can interpret HTML or load linked images. Inspect it there before publishing. Page metadata, private source and review notes, and history are excluded. For a Word document, start with <a href="/word-to-markdown/">Word to Markdown</a>. For article HTML, use <a href="/html-to-markdown/">HTML to Markdown</a>. Keep a private workspace backup separately if you need to resume editing.</p>' +
'<table class="format-table"><thead><tr><th scope="col">Format</th><th scope="col">Required</th><th scope="col">Use it for</th></tr></thead><tbody><tr><th scope="row">Article body (.md)</th><td>Article and review approval</td><td>Paste into an editor or continue working in another tool.</td></tr><tr><th scope="row">Page Markdown (.md)</th><td>All page fields and review approval</td><td>A Markdown website after checking its metadata requirements.</td></tr><tr><th scope="row">Reading page (.html)</th><td>Title, article, and review approval</td><td>Open a standalone article in a browser or manually place the file on static hosting.</td></tr></tbody></table>' +
'<p>All article formats exclude source notes and review questions. A private JSON workspace backup contains those and can preserve incomplete writing. <a href="/help/local-workspace/">Keep workspace backups private</a>.</p>' +
'<h2>Copy formatting or take a kit</h2><p>Copy formatted article provides basic article HTML and a plain-text fallback on the clipboard. Its title is optional. A publishing kit groups article files, page fields, and destination instructions in a ZIP. Source and private review notes are excluded. <a href="/help/publishing-handoff/">Follow the handoff guide</a>.</p><h2>Use a reading page</h2><ol><li>Enter a title and article, read the local preview, and approve the article.</li><li>Select Download reading page. Open the saved HTML file in a browser.</li><li>Check the title, paragraph breaks, headings, lists, emphasis, code, and quotations.</li><li>To host it, manually add the file to a static website directory that serves HTML, on a branch in your own repository. Use its preview before merging.</li></ol><p>The file is a complete HTML document with local styling, one page title heading, and no scripts or external assets. Simple inline links to absolute http:// or https:// addresses open a new tab when selected. Images, source HTML, and unsupported link formats remain text; this is a reading format, not a complete Markdown renderer. Your hosting rules may affect styling. No repository connection or upload occurs here.</p>' +
'<h2>Avoid a duplicate Markdown title</h2><p>Use Website supplies the title heading when your website renders the metadata title. Use Include a title heading in the file when you need a document with its own heading. Body export includes neither title nor metadata. Check any title heading already in your body; the editor does not silently remove authored content.</p>' +
'<h2>Page metadata</h2><pre class="code-sample"><code>---\ntitle: "Your article title"\nexcerpt: "A short introduction"\ndescription: "A page description"\ndraft: true\n---\n\nYour reviewed article body.</code></pre>' +
'<p>The filename uses your reviewed filename field. Other exports suggest a safe filename from the title when needed. Page Markdown does not provide a layout, date, or other fields your site may require. Adapt the file to the actual destination.</p>' +
'<h2>A manual GitHub handoff</h2><ol><li>Identify the repository content directory and whether it serves HTML or processes Markdown.</li><li>Use non-sensitive article material. A branch or pull request in a public repository is public.</li><li>Add the article on a feature branch and check metadata and title handling.</li><li>Run the website build and inspect its desktop and mobile preview.</li><li>Review before merging; the destination may publish automatically after a merge.</li></ol>' +
'<p>The exported draft flag is only metadata and works only when the destination honors it. The reading page has no publication lock. Keep private material outside public repositories.</p>' +
'<h2>Other website editors</h2><p>For a website editor, copy the article body and add title and page details separately. Markdown support varies. There is no direct WordPress, Squarespace, Ghost, or automatic publishing integration.</p>' +
'<p><a class="button" href="/write/#draft">Open the writing workspace</a> · <a href="/samples/studio.md">Inspect a fictional Markdown sample</a></p>');
const faqs = [
['Who can use the pilot?', 'The owner and invited testers only. Public examples, templates, and the sample editor need no account. There is no public registration, billing, or per-user password recovery.'],
['Why does the pilot say it is not activated?', 'Private access or usage protection has not been configured successfully. The public resources remain available. The owner should follow the activation checklist; an invited tester should contact the person who invited them.'],
['What does the sample editor do?', 'It loads prewritten fictional articles that you can edit and export in this browser tab. It does not call AI or demonstrate actual model quality.'],
['What does Article type change?', 'It selects one of three built-in writing presets. It does not learn your voice, save a custom website profile, or add facts to the notes.'],
['Does the tool research or fact-check?', 'No. The pilot asks the model to use supplied facts and identify open questions. Those instructions are not a guarantee of correctness. The model can still misstate or invent information.'],
['Why is generation unavailable after sign-in?', 'The AI credential may be missing, or a connection check may have failed. Use Recheck connection without refreshing your working tab. An authentication, billing, or provider-access problem requires the owner to inspect the private configuration.'],
['What happens when an attempt fails?', 'Your existing notes and draft stay in the open page. There is no automatic retry. Failed provider attempts count toward the shared limit. Review the error and deliberately decide whether to try again.'],
['How do shared limits work?', 'The whole pilot shares 20 reserved generation attempts per UTC day, at least 30 seconds apart. Failed provider attempts count. Signing out or using another browser does not reset the counters. The daily window resets at midnight UTC.'],
['Why can I not export yet?', 'The public workspace lists missing fields beside the export controls. Body export needs only the article and approval; a reading page also needs a title. Page Markdown requires title, excerpt, description, filename, and body. Editing notes or article fields clears approval.'],
['My session ended. How do I keep the draft?', 'Leave the working tab open. Follow the sign-in link in a new tab, sign in there, then return and select Recheck connection. Do not refresh the working tab: there is no autosave.'],
['The clipboard did not work. What now?', 'For template outlines, select and copy the visible text manually. For articles, use Download Markdown. Check that a real file arrived on your device before closing the workspace.'],
['Can I recover work after leaving?', 'There is no server recovery service or saved history. Restore an explicit private workspace backup if you downloaded one. Without a saved file or your own document, discarded writing may be unrecoverable.'],
['Where do my notes go?', 'In the private pilot, the source notes, selected article-type guidance, audience, and purpose go through Cloudflare to Anthropic when you select Prepare draft. Read the data-use notice. Public template copies and sample-editor edits do not call AI.'],
['Where do I report a problem?', 'Invited testers should use the direct contact route agreed with the owner. Do not paste passwords, API keys, private notes, or draft content into a public issue. Include the operation, approximate time, browser, and visible error without private material.']
];
add('/help/', 'Help and troubleshooting', 'Practical answers about pilot access, note preparation, review, export, shared limits, and preserving work when a session expires.', `${heading('Help', 'Finish the task without guessing.', 'Start with the first-use guide, check the export format, or find the error you are seeing below.')}${cards([['First article', 'Prepare notes and complete a reviewed export.', '/getting-started/', 'Follow the first-use guide'], ['Your exported file', 'Understand metadata, headings, and the publishing handoff.', '/help/markdown-export/', 'Read the export guide'], ['Publishing handoff', 'Copy formatted writing or take a ZIP with article files and next steps.', '/help/publishing-handoff/', 'Choose your handoff'], ['Draft checks', 'Find unfinished passages, navigate headings, and inspect link handoffs.', '/help/draft-checks/', 'Review a draft locally'], ['Access and status', 'Understand the public resources and invitation-only pilot.', '/access/', 'Check the access guidance']])}<section class="faq"><h2>Practical questions</h2>${faqs.map(([q, answer]) => `<details><summary>${q}</summary><p>${answer}</p></details>`).join('')}</section><p>${a('/privacy/', 'Read the complete data-use notice')} before submitting notes.</p>`, { wide: true });

add('/access/', 'Pilot access and activation', 'Understand what is public, what requires an invitation, and what the owner must verify before activating real AI generation.', `${heading('Access & status', 'Public resources. A private pilot.', 'Use the learning resources now. Live AI generation remains a small invitation-only test, not a public service.')}${notice(status)}
<h2>Available without signing in</h2><p>${a('/examples/', 'Complete fictional examples')}, ${a('/templates/', 'six note templates')}, ${a('/demo/', 'an editable sample workspace')}, and ${a('/help/', 'practical help')}. The public writing workspace also supports your own notes, a locally assembled drafting brief, explicit private backups, and article exports. These resources do not require a provider account and do not send your writing to AI.</p><h2>Already invited?</h2><p>${a('/pilot', 'Open the private pilot')} and use the password supplied through the owner's agreed private channel. There are no individual accounts or password-reset emails. When access is unavailable, contact the person who invited you rather than submitting credentials elsewhere.</p><h2>Not invited yet?</h2><p>Public applications are not open. There is no waiting-list form or automatic invitation process. Use the public resources to see whether the workflow fits your needs.</p><h2>Owner activation checklist</h2><p>This page does not inspect account settings or verify whether the AI provider is ready. The actual pilot page reports whether sign-in is available; the authenticated workspace reports generation configuration.</p><ol><li>Confirm the latest deployment succeeded for the existing Cloudflare Worker <code>drafttopage</code> and that its quota binding is present.</li><li>Configure the private pilot password and project-specific AI credential as runtime secrets, never in this public repository, browser scripts, or chat.</li><li>Set a small provider spending limit and review provider data handling before making a real request.</li><li>Use fictional notes for one owner-only generation test. Edit the result, approve it, download the actual file, and check that the edits are included.</li><li>Verify sign-out and anonymous access blocking. Confirm the provider usage and establish a direct support route before inviting testers.</li></ol><p>The full repository checklist is in <code>docs/ACTIVATION_CHECKLIST.md</code>. No access or spending limit should be bypassed to make the app appear available.</p><p>${a('/privacy/', 'Read the data-use notice')} · ${a('/getting-started/', 'Prepare for your first article')}</p>`);

add('/guides/source-notes/', 'Prepare useful source notes', 'Separate facts, interpretation, uncertainty, audience, and purpose before turning your material into a draft.', `${heading('Writing guide', 'Give the draft something real to work with.', 'The useful input is your substance, not a clever instruction to manufacture authority.')}
<h2>Start with one article-sized question</h2><p>Choose the single thing this page should explain. A short update about what you finished is easier to review than a request to summarize everything about a project.</p><h2>Separate three kinds of statement</h2><dl><dt>Observed or documented</dt><dd>What happened, what you did, or what a source actually establishes.</dd><dt>Interpretation</dt><dd>What you think it means. Make it clear that this is your reading of the situation.</dd><dt>Unresolved</dt><dd>What is uncertain, unconfirmed, or missing. Leave it as a question rather than filling the gap.</dd></dl><h2>Compare two possible inputs</h2><div class="paper"><p><strong>Too vague:</strong> Write an inspiring update about how our project is transforming the neighborhood.</p><p><strong>More reviewable, fictional input:</strong> Two volunteers checked a suggested reading list. We have not confirmed meeting dates or a venue. Explain the progress without implying that a meeting is scheduled.</p></div><h2>Include the audience and purpose</h2><p>“Neighbors considering a reading group” gives you a clearer editing target than “everyone.” “Explain what is complete and what remains undecided” is more specific than “make it engaging.”</p><h2>Remove material that should not be submitted</h2><p>Do not paste credentials, sensitive personal information, confidential business material, or someone else's writing without permission. Keep your full original notes in your own document and submit only what is needed.</p><h2>Stop when the notes are too thin</h2><p>The pilot is not a research service. When the important facts are missing, gather them first or publish a smaller claim. A shorter accurate piece is preferable to a padded article with invented substance.</p><p>${a('/templates/', 'Choose a copyable note template')} · ${a('/guides/review/', 'Review the eventual draft')}</p>`);

add('/guides/review/', 'Review an AI-assisted draft', 'A practical pre-publication checklist for factual claims, voice, uncertainty, permissions, metadata, and the publishing handoff.', `${heading('Review checklist', 'Approval is an editorial decision.', 'A smooth sentence can still be wrong. Read for claims and meaning before polishing the wording.')}
${steps([
['Compare the draft with your source', 'Look for names, dates, quotations, numbers, achievements, causal claims, and promises that were not supplied. Delete them or verify them independently. Do not assume they are true because the draft sounds confident.'],
['Preserve uncertainty', 'A test is not a proven result. A plan is not completed work. A personal interpretation is not an established fact. Check that the draft has not quietly erased those distinctions.'],
['Make the voice specific', 'Read the piece aloud. Replace vague enthusiasm and language you would not use. Add a concrete detail only when it is real and you have permission to share it.'],
['Check permissions and consequences', 'Confirm that quotations, personal stories, images, and identifying details can be published. Do not use this checklist as a substitute for professional review of high-stakes material.'],
['Resolve the open questions', 'The suggested questions may be incomplete. Answer them using your own knowledge or reliable sources. Save remaining questions outside the article export. A draft with no returned questions is not automatically verified.'],
['Check the complete package', 'Review title, excerpt, description, filename, and body together. The summary should not make a stronger claim than the article. Check the actual downloaded file and preview the destination before publishing.']
])}${notice('The review checkbox records your action in the current page. It is not a certificate of accuracy, an independent audit, or a permanent approval record.')}
<p>${a('/demo/', 'Practice reviewing a sample')} · ${a('/help/markdown-export/', 'Check the export handoff')}</p>`);

add('/privacy/', 'Data use', 'How public resources and the private pilot handle writing, sign-in, usage limits, unsaved work, and exports.', `${heading('Data use', 'Your writing, and where it goes.', 'Draft to Page is in development. The private pilot is an invitation-only test, not a public publishing service.')}
${notice('Do not submit sensitive personal data, confidential business information, passwords, or material you lack permission to use.')}
<h2>Public resources and the sample editor</h2><p>The examples and templates are public, fictional teaching material. Copying an outline and editing or exporting a prewritten sample do not call an AI service. Sample-editor edits stay in the open page; application code does not save them to browser storage or a server database. Refreshing or leaving can discard them. Hosting-provider operational processing is separate.</p><h2>When you generate a private-pilot draft</h2><p>Your notes, selected article-type guidance, audience, and purpose pass through the Cloudflare-hosted backend and are sent to Anthropic's Claude API. The response returns to your browser. The application does not browse for more information or publish anything.</p><p>The private pilot does not save notes or draft content to a server database, persistent browser storage, or application logs. The separate public tools offer explicit opt-in browser recovery as described below. That is not a promise of zero retention by infrastructure providers. Cloudflare and Anthropic process requests under their applicable policies, agreements, and account settings. Review those terms before using private material.</p><h2>Sign-in and usage protection</h2><p>A Secure, HttpOnly, SameSite sign-in cookie lasts up to four hours. Signing out removes it from that browser. Rotating the shared password invalidates sessions. There are no separate customer accounts or individual password-recovery features.</p><p>A Cloudflare Durable Object stores shared sign-in and generation counters and timestamps, not notes or drafts. The whole pilot shares 20 reserved generation attempts per UTC day, at least 30 seconds apart. Failed provider attempts count. Application code includes no analytics or advertising scripts.</p><h2>Local article imports and review notes</h2><p>Choosing an article file reads only that selected UTF-8 file in the browser. Pasted imports and local formatting also make no upload or AI request. An import preview is temporary and is not included in workspace backups until applied. Importing replaces article fields and review questions after any required confirmation while keeping source notes. Editable review notes are included in explicit private backups and excluded from article exports.</p><h2>Word text version previews</h2><p>When selected explicitly, ordinary tracked text insertions and deletions can be flattened into proposed or previous article text. The preview and revision counts stay temporarily in this tab; the original Word file is not rewritten. Revision author names, dates, and history are excluded. Only the applied article version enters ordinary backups and exports. Clearing or applying discards the pending source bytes and preview. Complex revisions remain unsupported. No upload, AI request, or persistent storage is added.</p><h2>Private Word comment recovery</h2><p>Explicit comment recovery reads the standard comments XML from the Word file already selected in this tab. It prepares plain feedback separately from the article, including unanchored comments, possible replies, and text hidden by Word styling. Author names, dates, thread relationships, anchors, resolved status, formatting, and hyperlink targets are not retained. Acknowledging the private report allows an unencrypted text download. Only comments you explicitly include become private review notes on article replacement; article exports exclude them. Applying or clearing the import discards its temporary recovery. Recovered reports stay temporary. Only comments explicitly added as workspace review notes can enter an enabled browser recovery copy. No comment text is uploaded or sent to AI.</p><h2>Formatted article imports</h2><p>When you explicitly choose formatted import, a user-initiated paste can read the HTML representation supplied by your clipboard. Selected UTF-8 HTML files are also read locally. Original HTML is parsed only in detached template contents; original nodes are never attached to the page and their resources are not fetched. The preview renders converted Markdown. Formatting changes and omissions need acknowledgement before applying. Normal article pasting remains plain text. Raw import text, pending previews, and import choices are temporary and excluded from backups. Applied converted article fields become ordinary workspace writing, with previous valid writing retained in an in-tab checkpoint. No upload, AI request, tracking, or automatic publication is added.</p><h2>Local article search and replacement</h2><p>Find and replace reads only the current article body. Its default conservative scope skips recognized code, links, URLs, and HTML markup; whole-word filtering is optional. Entire Markdown source can be selected explicitly. Queries, replacement settings, and at most five preview excerpts stay in tab memory and are excluded from private backups and article exports. Applying a replacement captures the previous writing in an in-tab checkpoint and clears approval. Importing/restoring a workspace or clearing the desk removes temporary search values and snippets. Source notes and review questions are not searched or replaced. Applied article text is handled as ordinary draft text. No AI request or upload is made.</p><h2>Source passage reviews</h2><p>The guided passage review reads your current article and source notes locally. Preparing a review keeps an exact short article passage, a source reference, evidence or explanation, and your decision temporarily in tab memory. Unsaved preparation is excluded from files. Saving adds or updates one of the existing twelve private review notes, keeps a checkpoint first, and clears export approval. Saved records stay in explicit workspace backups, checkpoints, and collection entries after Add or Update. Article exports exclude them. Review decisions are your own historical notes, not independent verification or a certification score. Current text matching locates only a unique exact passage. Article or source-note edits require explicit rechecking before saving pending work. Restore, article import, sample loading, and desk clearing discard unsaved preparation. Closing the review panel clears its temporary copy of source notes. Unsaved passage review preparation is excluded from browser recovery. Saved workspace review notes can enter an explicitly enabled recovery copy. No upload, AI request, URL lookup, tracking, or account is added.</p><h2>Private draft collections</h2><p>The public writer and converters can explicitly keep up to eight named workspace snapshots in tab memory and download them together as an unencrypted private JSON collection, within 2 MiB. Each saved entry contains article fields, source notes, audience, purpose, article type, and private review questions. Editor edits are included only after Add or Update. The file excludes approval, credentials, publishing profiles, checkpoints, collection undo, and pending imports. Article exports still contain only the current article. Selected collection files are validated and previewed locally; loading changes only saved entries, while opening an article separately checkpoints valid current writing and clears approval and profile settings. One previous collection state supports explicit undo and is never exported. Hidden saved-workspace inspection text is cleared on close. Clear this writing desk removes collection entries, undo, and pending reads from the tab. Exit warnings include collection writing and staged files. There is no collection autosave, browser persistence, server history, upload, tracking, account, or AI request. Download before leaving.</p><h2>Reusable publishing profiles</h2><p>A publishing profile is an explicitly downloaded JSON file containing its name, destination, title-handling choices, and up to eight user-written reminders. It excludes article fields, source notes, audience, purpose, private review questions, completion ticks, and approval. Reminder text itself can contain private information, so inspect it before sharing. Profiles are unencrypted and separate from workspace backups. Loading reads only the selected file locally and stages a preview; applying updates export choices without replacing writing and clears approval. Changes to writing or export choices reset temporary checklist ticks. Reminders are not factual verification and do not block exporting. Workspace restore, checkpoint restore, sample loading, and desk clearing remove the current profile name and checklist. There is no profile autosave, browser persistence, account, server storage, upload, tracking, or AI request.</p><h2>Focused converter views</h2><p>The WordPress, HTML, and Word tools place writing beside the reading preview and selected export on wider screens. Smaller screens use article, result, and notes in that order. Long desktop previews have a keyboard-focusable scroll region. More export options and preview-format help are collapsed initially; opening them changes only the local view. Closing More export options clears its temporary publishing-kit file list; selecting Other exports and page Markdown opens those options. The separate Markdown article destination exposes copying and downloading directly, without page metadata. No view choice, scroll position, approval, or temporary output is added to backups. Writing is unchanged by opening or closing these panels.</p><h2>Editable Word documents</h2><p>The Markdown to Word tool and Word document handoff generate a .docx file locally only when you choose Download Word. The file contains article text, basic document formatting, supported safe web hyperlinks, and a title only when selected. It excludes page metadata, source and review notes, audience, purpose, approval, settings, and checkpoints. No author metadata, source images, macros, embedded files, comments, or tracked changes are generated. Downloaded files are unencrypted and handled by your device. Opening a document or following its links is handled by your editor and the destination under their own policies. The Word file does not restore a workspace. No upload, AI request, tracking, account connection, or publication occurs here.</p><h2>Local Word imports</h2><p>Selecting a .docx reads it only in this tab and stages a conversion preview. Ordinary conversion decompresses only allowlisted document, style, numbering, footnote/endnote, and relationship XML parts, validates sizes and checksums, and leaves image and embedded-file bytes unread. XML stays detached; only converted Markdown reaches the reading preview. Document metadata, comments, headers, and footers are excluded. Supported referenced footnotes and endnotes become labeled article sections; unreferenced notes and separators are excluded. Note labels follow first visible reference, without native numbering, backlinks, or page-bottom placement. The appended text is included in article exports, unlike private workspace source notes and review questions. Notes with complex content, missing references, or excess size are rejected before applying. Images become numbered text placeholders; unsupported structures are rejected. Original file bytes and pending previews are temporary and excluded from workspace backups. Applying retains only converted article fields, keeps existing source notes, checkpoints valid previous writing, and clears approval. No upload, persistence, account, tracking, external resource fetch, or AI call is added.</p><h2>Explicit Word image recovery</h2><p>Prepare Word image files separately reads supported embedded PNG and JPEG parts from the selected document. Recovery maps the first 200 visible image or object positions and at most 40 unique files, each up to 4 MiB and together up to 12 MiB. Images are not displayed, uploaded, re-encoded, or fetched from links. The prepared ZIP contains original image bytes, converted article text, Word alternative text, numbered placement notes, and manual WordPress instructions. Original images can include metadata and areas hidden by Word cropping; crops, rotation, effects, and layout are not reproduced. Private workspace source and review notes are excluded. The package is unencrypted and requires a separate acknowledgement before an explicit download. Prepared bytes remain only in tab memory; discarding the package, applying or clearing the import, or leaving the page removes them. Image files are excluded from workspace backups, checkpoints, collections, profiles, and ordinary article exports. Your device handles downloaded files under its own policies. Uploading the recovered files to WordPress is a separate action you perform there.</p><h2>WordPress linked images</h2><p>Image preparation inspects only the current article locally. An explicit option can turn supported standalone HTTPS Markdown image references into native linked Image blocks in WordPress copies, downloads, and the WordPress kit. It defaults off and is excluded from private backups, checkpoints, collection entries, and publishing profiles. Body edits, import/restore/sample/clear, leaving WordPress, and applying or clearing a profile reset it. Changing the option clears export approval and temporary profile checklist completion. Local previews never fetch or display images; closing the image panel clears its reference list. Download image handoff notes and the kit REVIEW.txt include recognized image URLs and alt text from the article, excluding private source and review fields. Image text or URLs themselves can be private. Exported Image blocks can request their URLs when opened in WordPress or a browser. No file upload, Media Library copy, availability check, permission check, account connection, tracking, persistence, or AI request is added. Reading HTML, HTML source, formatted copies, and Word retain literal image syntax.</p><h2>Article Markdown</h2><p>The Markdown article destination prepares the current body and an optionally included title as a Markdown heading. It excludes page metadata, source and review notes, checkpoints, and credentials. The title choice is shared with page Markdown. Body text, including literal HTML and resource syntax, is retained; a destination can interpret it or load referenced resources. Hidden or unapproved prepared output is cleared. Copying writes to your clipboard, and downloading creates a local .md file. Neither action uploads or publishes writing. The Word to Markdown route uses the same local Word import and manual review flow. Its downloadable Word and Markdown samples are fictional public material.</p><h2>Reviewed HTML source</h2><p>The Markdown to HTML tool and HTML source handoff prepare only article markup in this tab. An explicit copy writes plain-text HTML code to your device clipboard, and an explicit download creates an article fragment. Title inclusion is optional; page metadata, private source and review notes, checkpoints, and sign-in values are excluded. Source HTML and images remain inert text. Editing or changing title handling clears approval; switching away from HTML source clears its hidden code. Fixed layout hints do not load external resources. No upload, tracking, AI request, or publication is added.</p><h2>Formatted copies and publishing kits</h2><p>Formatted copying explicitly writes reviewed article HTML and a plain-text representation to your device clipboard. The title is included only when selected. Browser permissions and destination rendering vary. A locally generated publishing ZIP contains only article files, page fields, and handoff instructions. Source notes, audience, purpose, article type, private review questions, and authentication fields are excluded. The WordPress kit also includes local article-derived handoff findings and a review checklist. Other temporary draft-check results are excluded. Article text itself can still contain private information. Kits are unencrypted and are separate from complete private workspace backups. No upload or publishing request occurs here.</p><h2>Optional Word image placement maps</h2><p>In the article image editor, explicitly selecting an extracted image-map.json reads that bounded UTF-8 JSON file locally. The map shows original Word placeholder labels, recovered filenames, alternative text, and omission notes. No image file, folder, ZIP, or URL is opened by this step. A manual comparison and separate action are required to reuse alternative text in pending image preparation. The map remains in tab memory until cleared, discarded with image preparation, or the workspace is replaced. It is excluded from workspace files, browser recovery, checkpoints, collections, and article exports. Only image Markdown explicitly applied to the article becomes saved or exported article text. Uploading an original image in another tool can disclose its metadata and areas hidden by Word cropping; inspect it first.</p><h2>Local draft checks and web links</h2><p>Draft checks and the section outline inspect the current article locally without AI, address lookups, or uploads. Results are temporary and excluded from backups and article exports. Word and HTML formatting reviews show destination-specific findings and title handling in the tab. Explicit review copying or downloading produces a separate text report with findings and article line numbers, excluding private source notes, review questions, and revision history. These checks do not load images or verify web addresses. Selected export content previews use current article content and destination options only. WordPress linked-image previews show inert URL and alternative-text placeholders; no image loads. Closing the preview or replacing the workspace clears prepared content. Preview state is excluded from files and persistent storage. Copy check summary is an explicit clipboard action. Supported absolute web links in the reading preview and HTML export open the destination in a new tab only when selected. A selected link is handled by the destination under its own data policies. Imported images and source HTML stay inert.</p><h2>Optional browser recovery in the public tools</h2><p>Browser recovery is off by default. With explicit consent in a public writer or converter, one unencrypted workspace copy is kept in this browser profile. It includes article fields, source notes, audience, purpose, article type, and saved review questions. Anyone using that browser profile may restore it. No upload or account sync is provided. Pending imports, original Word bytes, images, unsaved editing preparation, collections, checkpoints, approval, credentials, and publishing preferences are excluded.</p><p>Only one tab can write the copy, protected by an origin-scoped browser lock. Unsupported or blocked storage leaves file backups available. Storage errors stop saving and retain the last good copy when possible. Returning does not restore writing or enable saving automatically: inspect each saved/current field, acknowledge the comparison and local storage consent, then explicitly restore. Restore checkpoints valid displaced writing and clears approval. Pausing retains the copy; Remove browser copy deletes it after confirmation and leaves open writing intact. Confirmed desk clearing also removes the browser copy when it can do so safely. Storage can be cleared or evicted, so keep a downloaded backup for important work. No guaranteed recovery is offered. This feature is not in the private pilot.</p><h2>Public writing and workspace files</h2><p>The public writing workspace keeps your notes and article in the open tab. Loading outlines, preparing or copying a drafting brief, and exporting files make no AI request or upload. If you paste a brief into another tool, that tool processes it under its own data policies.</p><p>An explicit private JSON backup contains notes, audience, purpose, article type, article fields, and imported review questions. It excludes application authentication values, consent, approval, and export-format preferences. It is unencrypted. Your device may sync downloaded files through its own services. Keep workspace files out of public repositories.</p><p>Restore reads and validates a selected file locally, then stages it for explicit review. Field comparisons and an article preview remain in tab memory. Selecting or discarding a file does not replace writing or clear approval. Applying a reviewed restore replaces the whole workspace, clears approval and pilot consent, and makes no AI request. Public restores first checkpoint previous valid writing. Preview contents are excluded from backups and article exports, and are cleared when discarded, applied, or when the public workspace is replaced or cleared. Restore cannot recover writing that you did not save.</p><h2>Revision checkpoints in the public workspace</h2><p>Revisions in this tab keeps at most five versions and 2 MiB of serialized writing in tab memory. Checkpoints contain source notes, audience, purpose, article type, article fields, and private review notes. You can save one explicitly; imports, workspace restores, formatting, filename suggestions, outline replacements, and review-note removal also retain previous writing before mutation. No timer, keystroke autosave, persistent browser storage, or server history is added.</p><p>Comparison displays saved and current field text as data. Article changes compares article bodies as added and removed lines, with bounded processing and a grouped fallback for large changes. Its temporary text is excluded from backups and exports and is removed when the workspace is cleared. Restoring requires confirmation, clears approval and export preferences, and retains displaced writing when nonempty. The oldest checkpoints are removed at the limits. Clearing the writing desk removes all writing and checkpoints in that tab. A selected private checkpoint download requires acknowledgement and includes one version in the existing workspace JSON format, without labels or history. Article exports exclude checkpoint history and private source/review fields.</p><h2>Unsaved writing and exports</h2><p>The editor keeps writing in the open page. Refreshing, leaving, clearing, or signing out can discard it. Browser recovery in the public tools is optional and off by default. It provides one local copy, not a version history or server recovery service. The private pilot has no browser recovery. In-tab checkpoints can also be lost when you refresh or leave; download an explicit private backup to keep a version beyond this tab. Clipboard copies and downloaded files are handled by your device and are outside the application's control.</p><p>Page Markdown exports include metadata and a draft flag; article-body exports contain only the body. Standalone reading pages contain the title, basic article formatting, and an optional page description, with no scripts or external assets. All article formats omit source notes and review questions. Save those separately in your own private document. Review Markdown, links, and markup in a safe editor before publishing. The pilot does not guarantee factual accuracy or sanitize output for every publishing platform.</p><h2>Questions and pilot participation</h2><p>Before inviting testers, the owner must verify provider settings and spending controls, explain the shared-password arrangement, and establish a direct contact route. Invited testers should use that agreed route for access or data-use questions. No public sign-up, payment collection, or marketing mailing list is enabled.</p><p><a href="https://privacy.anthropic.com/" rel="noreferrer">Anthropic privacy information</a> · <a href="https://www.cloudflare.com/privacypolicy/" rel="noreferrer">Cloudflare privacy policy</a></p><p>${a('/access/', 'Access and activation')} · ${a('/help/', 'Practical help')}</p>`);

add('/404.html', 'Page not found', 'Find Draft to Page examples, templates, practical help, and private-pilot access.', `${heading('Page not found', 'That page is not here.', 'The address may have changed. Your next step is still available.')}${cards([['Try a sample', 'Edit and export prewritten fictional material without signing in.', '/demo/', 'Open the sample editor'], ['Prepare your notes', 'Choose one of six copyable outlines.', '/templates/', 'Browse templates'], ['Get help', 'Find access, review, and export guidance.', '/help/', 'Open help']])}`, { wide: true });

add('/about/', 'About and support', 'Draft to Page is an independent project by Nolan Kido. Learn its purpose, development status, and how to report a public issue.',
heading('About the project', 'Your substance. A clearer path to a page.', 'Draft to Page is an independent project by Nolan Kido, built for people maintaining their own websites.') +
'<h2>What we are building</h2><p>A focused workflow for turning your own material into an article you can review and take into your publishing system. Source notes, uncertainty, and author approval are part of the process.</p><h2>What you can use today</h2><p>The public writing workspace, six note outlines, three fictional examples, explicit private backups, and reviewed article exports. The public workspace is manual. The private AI pilot requires owner activation and genuine acceptance testing.</p><h2>Follow the work</h2><p><a href="https://github.com/nolankido/drafttopage" rel="noreferrer">View the public source on GitHub</a>. You can inspect implementation and development status there. <a href="https://nolankido.com/" rel="noreferrer">Learn more about Nolan Kido</a>.</p><h2>Report a problem</h2><p><a href="https://github.com/nolankido/drafttopage/issues" rel="noreferrer">Open the public issue list</a> for bugs in the public tools. Include the action, browser, and visible error using fictional examples. Keep private writing, passwords, and credentials out of public issues. Invited pilot testers should use the private contact route agreed with the owner.</p><p><a href="/access/">Access and development status</a> · <a href="/privacy/">Data use</a></p>');
for (const page of writingPages) pages.set(page.route, renderPage(page));
const outputRoot = process.argv[2] || 'public';
for (const [path, html] of pages) {
  const file = path === '/404.html' ? join(outputRoot, '404.html') : join(outputRoot, path.slice(1), 'index.html');
  await mkdir(dirname(file), { recursive: true }); await writeFile(file, html);
}
await mkdir(join(outputRoot, 'samples'), { recursive: true });
for (const example of EXAMPLES) await writeFile(join(outputRoot, 'samples', example.id + '.md'), createMarkdown(example.draft));
await writeFile(join(outputRoot, 'samples', 'word-to-markdown.docx'), createWordDocument(WORD_MARKDOWN_SAMPLE, { includeTitle: true }));
await writeFile(join(outputRoot, 'samples', 'word-to-markdown.md'), createArticleMarkdown(WORD_MARKDOWN_SAMPLE, { includeTitle: true }));
const indexable = [...pages.keys()].filter(path => path !== '/404.html');
await writeFile(join(outputRoot, 'sitemap.xml'), '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + indexable.map(path => '  <url><loc>https://drafttopage.com' + path + '</loc></url>').join('\n') + '\n</urlset>\n');
await writeFile(join(outputRoot, 'robots.txt'), 'User-agent: *\nDisallow: /pilot\nDisallow: /api/\nSitemap: https://drafttopage.com/sitemap.xml\n');
await writeFile(join(outputRoot, 'release.json'), JSON.stringify({ release: RELEASE, publicPages: indexable.length, exampleType: 'illustrative', publicAIGeneration: false, localWritingDesk: true, workspaceBackups: true, draftingBrief: true, readingPageExport: true, localDraftChecks: true, articleOutline: true, safeReadingLinks: true, formattedClipboard: true, publishingKit: true, pasteFirst: true, workingSample: true, wordpressBlocks: true, wordpressHandoffReview: true, wordpressKit: true, wordpressConverterTool: true, markdownTables: true, nestedLists: true, listStartValues: true, longDrafts: true, pasteLimitProtection: true, htmlSource: true, markdownHTMLTool: true, formattedArticleImport: true, readableImportPreview: true, wordDocumentExport: true, markdownWordTool: true, focusedConverters: true, publishingProfiles: true, reusablePublishingChecklist: true, privateDraftCollections: true, sourcePassageReview: true, wordpressLinkedImages: true, wordDocumentImport: true, wordToWordPressTool: true, guidedImageEditor: true, wordImagePlaceholderReplacement: true, guidedLinkEditor: true, articleLinkInventory: true, guidedTableEditor: true, articleImportInsertion: true, googleDocsWordPressTool: true, copiedWritingPreview: true, simplifiedFirstUse: true, groupedConverterTools: true, wordImageRecovery: true, wordImagePlacementKit: true, nestedInlineFormatting: true, styledLinkLabels: true, checkedInlineImport: true, guidedConversionSteps: true, explicitWorkflowScrolling: true, articleMarkdownExport: true, wordMarkdownTool: true, downloadableWordSample: true, wordFootnoteImport: true, wordEndnoteImport: true, wordNotesAsArticleText: true, previewPassageNavigation: true, exactPreviewSourceRanges: true, referenceLinkPreparation: true, referenceLinkSourcePreview: true, reviewedWorkspaceRestore: true, backupFieldComparison: true, destinationFormattingReview: true, wordHTMLFormatFindings: true, downloadableFormattingReview: true, destinationContentPreview: true, safeLinkedImagePreview: true, markdownFilePreview: true, readableWorkspaceLayout: true, optionalSideBySideLayout: true, directReturnToEditor: true, privateWordCommentRecovery: true, wordCommentReviewNotes: true, protectedArticleSearch: true, wholeWordSearch: true, wordTextRevisionPreview: true, setextHeadings: true, thematicBreaks: true, htmlMarkdownTool: true, explicitHTMLSourceImport: true, relativeHTMLLinks: true, explicitHTMLLinkContext: true }) + '\n');
